// geminiService.ts
import { GoogleGenAI } from "@google/genai";

/**
 * NOTE:
 * - Di AI Studio Build mode, pakai placeholder env: process.env.GEMINI_API_KEY
 * - Jangan hardcode API key di client side. (lihat docs Build mode)
 */
const ai = new GoogleGenAI({
  apiKey: (process.env.GEMINI_API_KEY as string) || "",
});

const MODEL_ID = "gemini-2.5-flash"; // cepat & bagus untuk ekstrak teks dari gambar :contentReference[oaicite:2]{index=2}

const SYSTEM_INSTRUCTION = `
Kamu adalah “Extractor & Formatter Jadwal Misa”.
Tugasmu: mengubah gambar tabel jadwal (mirip Excel) menjadi teks jadwal siap copas ke WhatsApp sesuai format yang ditentukan.

ATURAN UTAMA
1) Output hanya berupa TEKS (plain text). Jangan pakai tabel. Jangan jelaskan proses.
2) Salin semua data apa adanya dari gambar: judul misa, HR/perayaan, tanggal, hari, jam, daftar petugas P1..P7, termasuk ejaan, titik, koma, gelar, dan spasi.
3) Jika ada ikon/penanda kecil di samping nama (misal coretan/lingkaran/tanda khusus), ubah menjadi emoji “💦” di belakang nama (beri spasi sebelum 💦).
4) Format output harus konsisten persis seperti template:
   - Bagian “Note” selalu ditampilkan di paling atas (persis 3 baris note).
   - Setelah Note, tampilkan setiap Misa sebagai blok.
   - Antar blok misa beri jarak baris kosong (minimal 2 baris kosong).
5) Urutan misa mengikuti urutan kemunculan pada gambar (kiri ke kanan, atas ke bawah).
6) Jam selalu tulis “WIB”. Jika tidak tertulis WIB, tetap gunakan WIB.
7) “Warna Liturgi” tentukan dari warna dominan header/tema blok misa:
   - Hijau → 💚💚💚
   - Putih → 🤍🤍🤍
   - Merah → ❤️❤️❤️
   - Ungu → 💜💜💜
   - Pink → 💗💗💗
   - Hitam → 🖤🖤🖤
   - Emas/Kuning → 💛💛💛
   Jika ragu, pilih 🤍🤍🤍.
8) Penulisan tanggal:
   - Untuk format “Misa Jumat Pertama” gunakan: “🗓️ : <Hari> / <Tanggal Bulan Tahun>”
   - Untuk misa bernomor gunakan:
     “📅 <Hari>, <Tanggal Bulan Tahun>”
   Hari wajib Bahasa Indonesia: Senin, Selasa, Rabu, Kamis, Jumat, Sabtu, Minggu.
9) Penulisan jam:
   - Misa Jumat Pertama: “⏰ : HH:MM WIB”
   - Misa bernomor: “🕔 HH:MM WIB”
10) Penulisan judul:
   - Jika blok punya tema (misal HR PENAMPAKAN TUHAN), format:
     “Misa <emoji nomor> – <TEMA>”
   - Jika blok “Jumat Pertama”, format:
     “Misa Jumat Pertama”
11) Daftar petugas per baris: “P1. Nama”, “P3. Nama”, dst sesuai yang ada di gambar.

TEMPLATE NOTE (WAJIB DI ATAS)
Note :
▪️PIC Keluarkan 2~3 Sibori
▪️Purificatorium ambil di Meja Kreden
⚠️Hadir 30 menit sebelum Misa dimulai

Jika ada bagian yang tidak terbaca, tulis “[tidak terbaca]” pada bagian itu (jangan mengarang).
`.trim();

function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Gagal membaca file."));
    reader.onload = () => {
      const result = reader.result;
      if (typeof result !== "string") return reject(new Error("FileReader result bukan string."));
      // result format: data:image/jpeg;base64,XXXX
      const commaIdx = result.indexOf(",");
      if (commaIdx < 0) return reject(new Error("Format data URL tidak valid."));
      resolve(result.slice(commaIdx + 1));
    };
    reader.readAsDataURL(file);
  });
}

export async function convertExcelImageToText(imageFile: File): Promise<string> {
  if (!imageFile) throw new Error("File gambar belum dipilih.");

  const mimeType = imageFile.type || "image/jpeg";
  const base64 = await fileToBase64(imageFile);

  const userPrompt = `
Ubah gambar jadwal misa ini menjadi teks WhatsApp sesuai aturan format.
Pastikan:
- “Note” selalu ada di paling atas.
- Setiap misa jadi blok terpisah.
- Tambahkan 💦 hanya untuk nama yang punya tanda khusus di gambar.
- Warna Liturgi sesuai warna header/tema blok.
Keluarkan hasil final saja (tanpa penjelasan).
`.trim();

  // Multimodal: inlineData + text prompt :contentReference[oaicite:3]{index=3}
  const resp = await ai.models.generateContent({
    model: MODEL_ID,
    // beberapa versi SDK mendukung systemInstruction di sini
    systemInstruction: SYSTEM_INSTRUCTION,
    contents: [
      {
        inlineData: {
          mimeType,
          data: base64,
        },
      },
      { text: userPrompt },
    ],
  });

  const text = (resp as any)?.text ?? "";
  if (!text.trim()) throw new Error("Model tidak mengembalikan teks.");
  return text.trim();
}

