import React, { useState, useRef } from 'react';
import { geminiService } from '../services/geminiService';

const ScheduleModule: React.FC = () => {
  const [image, setImage] = useState<string | null>(null);
  const [result, setResult] = useState<string>('');
  const [isExtracting, setIsExtracting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = () => {
      setImage(reader.result as string);
      setResult('');
      setError(null);
    };
    reader.readAsDataURL(file);
  };

  const handleExtract = async () => {
    if (!image) return;

    setIsExtracting(true);
    setError(null);

    try {
      const base64Data = image.split(',')[1];
      const mimeType = image.split(',')[0].split(':')[1].split(';')[0];
      const extractedText = await geminiService.convertScheduleImageToText(base64Data, mimeType);
      setResult(extractedText);
    } catch (err: any) {
      console.error(err);
      setError("Failed to extract schedule. Please ensure the image is clear and try again.");
    } finally {
      setIsExtracting(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(result);
    // Simple feedback could be added here
  };

  return (
    <div className="flex flex-col h-full space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-slate-100">Mass Schedule Formatter</h2>
          <p className="text-slate-400 text-sm">Convert Excel/table images into clean WhatsApp schedules.</p>
        </div>
        {result && (
          <button
            onClick={copyToClipboard}
            className="flex items-center space-x-2 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg transition-colors font-medium"
          >
            <i className="fa-solid fa-copy"></i>
            <span>Copy for WhatsApp</span>
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 flex-1 min-h-0">
        {/* Left Side: Upload & Preview */}
        <div className="bg-slate-800/30 rounded-2xl border border-slate-800 p-6 flex flex-col space-y-4 overflow-hidden">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-semibold text-slate-300 uppercase tracking-wider">Source Image</h3>
            <button
              onClick={() => fileInputRef.current?.click()}
              className="text-xs text-indigo-400 hover:text-indigo-300 transition-colors"
            >
              Change Image
            </button>
          </div>

          {!image ? (
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="flex-1 border-2 border-dashed border-slate-700 rounded-xl flex flex-col items-center justify-center space-y-4 cursor-pointer hover:border-indigo-500/50 hover:bg-slate-800/40 transition-all"
            >
              <div className="w-16 h-16 rounded-full bg-slate-800 flex items-center justify-center">
                <i className="fa-solid fa-cloud-arrow-up text-2xl text-slate-500"></i>
              </div>
              <div className="text-center">
                <p className="text-slate-300 font-medium">Click or Drag to Upload</p>
                <p className="text-slate-500 text-xs mt-1">Supports PNG, JPG, JPEG</p>
              </div>
            </div>
          ) : (
            <div className="flex-1 relative rounded-xl overflow-hidden bg-black/20">
              <img src={image} alt="Source" className="w-full h-full object-contain" />
              <div className="absolute inset-0 bg-gradient-to-t from-slate-900/60 to-transparent pointer-events-none"></div>
            </div>
          )}

          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileChange}
            accept="image/*"
            className="hidden"
          />

          <button
            onClick={handleExtract}
            disabled={!image || isExtracting}
            className={`w-full py-3 rounded-xl font-bold transition-all flex items-center justify-center space-x-2 ${
              !image || isExtracting
                ? 'bg-slate-700 text-slate-500 cursor-not-allowed'
                : 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg shadow-indigo-600/20'
            }`}
          >
            {isExtracting ? (
              <>
                <i className="fa-solid fa-circle-notch animate-spin"></i>
                <span>Analyzing Table...</span>
              </>
            ) : (
              <>
                <i className="fa-solid fa-wand-magic-sparkles"></i>
                <span>Format Schedule</span>
              </>
            )}
          </button>
        </div>

        {/* Right Side: Result */}
        <div className="bg-slate-800/30 rounded-2xl border border-slate-800 p-6 flex flex-col space-y-4 overflow-hidden">
          <h3 className="text-sm font-semibold text-slate-300 uppercase tracking-wider">Extracted Text</h3>

          <div className="flex-1 bg-slate-900/50 rounded-xl p-4 overflow-y-auto border border-slate-800/50">
            {isExtracting ? (
              <div className="h-full flex flex-col items-center justify-center space-y-4 text-slate-500">
                <div className="w-8 h-8 border-2 border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin"></div>
                <p className="text-sm animate-pulse">Reading headers and rows...</p>
              </div>
            ) : result ? (
              <pre className="text-slate-200 text-sm font-mono whitespace-pre-wrap leading-relaxed">
                {result}
              </pre>
            ) : error ? (
              <div className="h-full flex flex-col items-center justify-center text-rose-400 space-y-2">
                <i className="fa-solid fa-circle-exclamation text-xl"></i>
                <p className="text-center px-4">{error}</p>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-600 italic">
                <p>Upload an image and click extract to see results.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ScheduleModule;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import ChatModule from './components/ChatModule';
import VoiceModule from './components/VoiceModule';
import ScheduleModule from './components/ScheduleModule';
import { AppView } from './types';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.SCHEDULE);

  const renderView = () => {
    switch (currentView) {
      case AppView.SCHEDULE:
        return <ScheduleModule />;
      case AppView.CHAT:
        return <ChatModule />;
      case AppView.VOICE:
        return <VoiceModule />;
      case AppView.DASHBOARD:
        return (
          <div className="h-full flex items-center justify-center">
            <div className="text-center space-y-4 max-w-lg">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-indigo-600/30">
                <i className="fa-solid fa-sparkles text-3xl text-white"></i>
              </div>
              <h2 className="text-3xl font-bold">Welcome to Gemini Creative Studio</h2>
              <p className="text-slate-400 leading-relaxed">
                Select a tool from the sidebar to begin. Whether you're formatting complex schedules, 
                chatting with an AI assistant, or generating multimedia assets, we have you covered.
              </p>
            </div>
          </div>
        );
      default:
        return (
          <div className="h-full flex items-center justify-center text-slate-500">
            Coming soon: {currentView}
          </div>
        );
    }
  };

  return (
    <div className="flex h-screen w-full bg-slate-950 text-slate-100 overflow-hidden font-sans">
      <Sidebar currentView={currentView} setView={setCurrentView} />
      <main className="flex-1 p-8 overflow-hidden relative">
        {/* Background glow effects */}
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-600/10 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[30%] h-[30%] bg-cyan-600/10 blur-[120px] rounded-full"></div>

        <div className="h-full relative z-10">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

export default App;

