import React, { useState, useRef, useCallback } from 'react';
import { geminiService, encode, decode, decodeAudioData } from '../services/geminiService';
import { LiveServerMessage, Blob } from '@google/genai';

const VoiceModule: React.FC = () => {
  const [isActive, setIsActive] = useState(false);
  const sessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Proper cleanup of audio nodes and the live session
  const cleanup = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (audioContextInRef.current) audioContextInRef.current.close();
    if (audioContextOutRef.current) audioContextOutRef.current.close();

    sourcesRef.current.forEach(s => {
      try {
        s.stop();
      } catch (e) {
        // Ignore errors from already stopped nodes
      }
    });
    sourcesRef.current.clear();
    setIsActive(false);
    nextStartTimeRef.current = 0;
  }, []);

  // PCM encoding helper for audio input stream
  const createPCMData = (data: Float32Array): Blob => {
    const int16 = new Int16Array(data.length);
    for (let i = 0; i < data.length; i++) {
      int16[i] = data[i] * 32768;
    }
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  };

  // Start the low-latency voice interaction session
  const startSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioContextInRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      audioContextOutRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const sessionPromise = geminiService.connectLive({
        onopen: () => {
          setIsActive(true);
          const source = audioContextInRef.current!.createMediaStreamSource(stream);
          const processor = audioContextInRef.current!.createScriptProcessor(4096, 1, 1);

          processor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const pcmBlob = createPCMData(inputData);
            // CRITICAL: Ensure data is only sent after the session connection resolves to avoid race conditions
            sessionPromise.then(session => {
              session.sendRealtimeInput({ media: pcmBlob });
            });
          };

          source.connect(processor);
          processor.connect(audioContextInRef.current!.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          const audioBase64 = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (audioBase64 && audioContextOutRef.current) {
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, audioContextOutRef.current.currentTime);
            const audioBuffer = await decodeAudioData(decode(audioBase64), audioContextOutRef.current, 24000, 1);
            const source = audioContextOutRef.current.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(audioContextOutRef.current.destination);
            // Schedule the next audio chunk for seamless playback
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }

          if (message.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => {
              try { s.stop(); } catch(e) {}
            });
            sourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }
        },
        onerror: (e) => {
          console.error("Live API Error:", e);
          cleanup();
        },
        onclose: () => {
          cleanup();
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error("Failed to start voice session:", err);
    }
  };

  return (
    <div className="h-full flex flex-col items-center justify-center space-y-8">
      <div className="relative">
        <div className={`w-48 h-48 rounded-full flex items-center justify-center transition-all duration-500 shadow-2xl ${
          isActive ? 'bg-indigo-600 scale-110 shadow-indigo-500/50' : 'bg-slate-800'
        }`}>
          <i className={`fa-solid fa-microphone text-6xl ${isActive ? 'text-white' : 'text-slate-500'}`}></i>
          {isActive && (
            <>
              <div className="absolute inset-0 rounded-full border-4 border-indigo-400 animate-ping opacity-25"></div>
              <div className="absolute inset-[-20px] rounded-full border border-indigo-500 animate-pulse opacity-10"></div>
            </>
          )}
        </div>
      </div>

      <div className="text-center max-w-md">
        <h3 className="text-2xl font-bold text-slate-100 mb-2">
          {isActive ? "Listening and Responding" : "AI Voice Interaction"}
        </h3>
        <p className="text-slate-400">
          {isActive 
            ? "Speak naturally. Gemini is listening and will respond with low-latency audio."
            : "Click the button below to start a real-time voice conversation with Gemini."}
        </p>
      </div>

      <button
        onClick={isActive ? cleanup : startSession}
        className={`px-8 py-4 rounded-full font-bold text-lg flex items-center space-x-3 transition-all ${
          isActive 
            ? 'bg-rose-500 hover:bg-rose-600 text-white' 
            : 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg shadow-indigo-500/30'
        }`}
      >
        <i className={`fa-solid ${isActive ? 'fa-stop' : 'fa-play'}`}></i>
        <span>{isActive ? "End Session" : "Start Conversation"}</span>
      </button>

      {isActive && (
        <div className="flex space-x-2">
          {[1,2,3,4,5].map(i => (
            <div key={i} className="w-1 h-8 bg-indigo-500 animate-pulse rounded-full" style={{ animationDelay: `${i * 0.15}s` }}></div>
          ))}
        </div>
      )}
    </div>
  );
};

