                  <i className="fa-solid fa-triangle-exclamation text-2xl"></i>
                </div>
                <div className="space-y-2">
                  <p className="font-semibold text-rose-300">Extraction Failed</p>
                  <p className="text-sm text-slate-400 leading-relaxed max-w-xs mx-auto">{error}</p>
                </div>
                <button 
                  onClick={handleExtract}
                  className="mt-4 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-full text-xs font-bold border border-slate-700 transition-all flex items-center space-x-2 mx-auto"
