import React, { useState, useRef } from 'react';
import { geminiService } from '../services/geminiService';

interface ScheduleBlock {
  title: string;
  content: string;
  type: 'note' | 'misa';
}

const STATIC_NOTE: ScheduleBlock = {
  title: 'Note',
  type: 'note',
  content: `Note : 
▪️PIC Keluarkan 2~3 Sibori
▪️Purificatorium ambil di Meja Kreden
⚠️Hadir 30 menit sebelum Misa dimulai`
};

const ScheduleModule: React.FC = () => {
  const [image, setImage] = useState<string | null>(null);
  const [blocks, setBlocks] = useState<ScheduleBlock[]>([]);
  const [isExtracting, setIsExtracting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copyStatus, setCopyStatus] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = () => {
      setImage(reader.result as string);
      setBlocks([]);
      setError(null);
    };
    reader.readAsDataURL(file);
  };

  const handleExtract = async () => {
    if (!image) return;

    setIsExtracting(true);
    setError(null);
    setBlocks([]);

    try {
      const base64Data = image.split(',')[1];
      const mimeType = image.split(',')[0].split(':')[1].split(';')[0];
      const resultBlocks = await geminiService.convertScheduleImageToText(base64Data, mimeType);

      // Prepend the mandatory static note
      setBlocks([STATIC_NOTE, ...resultBlocks]);
    } catch (err: any) {
      console.error("Extraction error:", err);

      const errMsg = err.message || "";
      if (errMsg === "IMAGE_UNCLEAR" || errMsg.includes("SyntaxError")) {
        setError("Silakan unggah gambar yang lebih jelas. Gambar saat ini terlalu buram untuk dibaca sistem.");
      } else {
        setError("Terjadi kesalahan saat mengekstrak data. Pastikan koneksi stabil dan gambar berisi tabel jadwal.");
      }
    } finally {
      setIsExtracting(false);
    }
  };

  const copyBlock = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopyStatus(id);
    setTimeout(() => setCopyStatus(null), 2000);
  };

  // Basic formatter to render WhatsApp bold (*) in the UI for preview
  const renderFormattedText = (text: string) => {
    const parts = text.split(/(\*.*?\*)/g);
    return parts.map((part, i) => {
      if (part.startsWith('*') && part.endsWith('*')) {
        return <strong key={i} className="text-white font-bold">{part.slice(1, -1)}</strong>;
      }
      return part;
    });
  };

  return (
    <div className="flex flex-col h-full space-y-6">
      <style>
        {`
          @keyframes shimmer {
            0% { background-position: -200% 0; }
            100% { background-position: 200% 0; }
          }
          .animate-shimmer {
            background: linear-gradient(90deg, #4f46e5 25%, #6366f1 50%, #4f46e5 75%);
            background-size: 200% 100%;
            animation: shimmer 1.5s infinite linear;
          }
        `}
      </style>

      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-slate-100">Formater Jadwal Prodiakon Kristus Raja</h2>
          <p className="text-slate-400 text-sm">Konversi tabel jadwal menjadi blok teks WhatsApp dengan formatting otomatis.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 flex-1 min-h-0 overflow-hidden">
        {/* Left Side: Upload & Preview */}
        <div className="bg-slate-800/30 rounded-2xl border border-slate-800 p-6 flex flex-col space-y-4 overflow-hidden shadow-inner">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-semibold text-slate-300 uppercase tracking-wider">Source Table</h3>
            {image && (
              <button
                onClick={() => fileInputRef.current?.click()}
                className="text-xs text-indigo-400 hover:text-indigo-300 transition-colors"
              >
                Ganti Gambar
              </button>
            )}
          </div>

          {!image ? (
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="flex-1 border-2 border-dashed border-slate-700 rounded-xl flex flex-col items-center justify-center space-y-4 cursor-pointer hover:border-indigo-500/50 hover:bg-slate-800/40 transition-all"
            >
              <div className="w-16 h-16 rounded-full bg-slate-800 flex items-center justify-center">
                <i className="fa-solid fa-cloud-arrow-up text-2xl text-slate-500"></i>
              </div>
              <div className="text-center px-4">
                <p className="text-slate-300 font-medium">Upload Jadwal (Foto/Screenshot)</p>
                <p className="text-slate-500 text-xs mt-1">Sistem akan mengekstrak teks dan petugas secara otomatis</p>
              </div>
            </div>
          ) : (
            <div className="flex-1 relative rounded-xl overflow-hidden bg-black/40 border border-slate-700">
              <img src={image} alt="Source" className="w-full h-full object-contain" />
            </div>
          )}

          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileChange}
            accept="image/*"
            className="hidden"
          />

          <button
            onClick={handleExtract}
            disabled={!image || isExtracting}
            className={`w-full py-4 rounded-xl font-bold transition-all flex items-center justify-center space-x-2 relative overflow-hidden ${
              !image
                ? 'bg-slate-700 text-slate-500 cursor-not-allowed'
                : isExtracting
                ? 'animate-shimmer text-white shadow-lg shadow-indigo-600/20'
                : 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-lg shadow-indigo-600/20'
            }`}
          >
            {isExtracting ? (
              <>
                <i className="fa-solid fa-wand-sparkles animate-spin text-sm"></i>
                <span className="relative z-10">Sedang Memproses...</span>
              </>
            ) : (
              <>
                <i className="fa-solid fa-bolt"></i>
                <span>Ekstrak & Format Jadwal</span>
              </>
            )}
          </button>
        </div>

        {/* Right Side: Framed Results */}
        <div className="bg-slate-800/20 rounded-2xl border border-slate-800 flex flex-col overflow-hidden">
          <div className="p-6 border-b border-slate-800 flex items-center justify-between shrink-0">
            <h3 className="text-sm font-semibold text-slate-300 uppercase tracking-wider">Hasil (Siap Copas)</h3>
            {blocks.length > 0 && (
              <span className="text-[10px] bg-indigo-500/20 text-indigo-400 px-2 py-1 rounded-full border border-indigo-500/30 font-mono">
                {blocks.length} BLOK
              </span>
            )}
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-6">
            {isExtracting ? (
              <div className="h-full flex flex-col items-center justify-center space-y-6 text-slate-500">
                <div className="relative">
                  <div className="w-16 h-16 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
                  <i className="fa-solid fa-magnifying-glass absolute inset-0 flex items-center justify-center text-indigo-400 animate-pulse"></i>
                </div>
                <div className="text-center">
                  <p className="text-indigo-300 font-medium">Membaca Tabel...</p>
                  <p className="text-xs text-slate-500 mt-2 italic">Mendeteksi format bold, warna liturgi, dan petugas</p>
                </div>
              </div>
            ) : error ? (
              <div className="h-full flex flex-col items-center justify-center text-rose-400 space-y-4 px-8 text-center">
                <div className="w-12 h-12 bg-rose-500/10 rounded-full flex items-center justify-center mb-2">
                  <i className="fa-solid fa-triangle-exclamation text-xl"></i>
                </div>
                <div className="space-y-2">
                  <p className="font-semibold text-rose-300">Gagal Ekstrak</p>
                  <p className="text-sm text-slate-400 leading-relaxed">{error}</p>
                </div>
                <button 
                  onClick={handleExtract}
                  className="mt-4 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-full text-xs font-bold border border-slate-700 transition-all"
                >
                  Coba Lagi
                </button>
              </div>
            ) : blocks.length > 0 ? (
              blocks.map((block, idx) => (
                <div 
                  key={idx} 
                  className={`relative group bg-slate-900/60 rounded-xl border transition-all hover:shadow-xl hover:shadow-indigo-500/5 ${
                    block.type === 'note' ? 'border-amber-500/40 shadow-lg shadow-amber-500/5' : 'border-slate-800 hover:border-indigo-500/40'
                  }`}
                >
                  <div className={`flex items-center justify-between px-4 py-2 rounded-t-xl border-b ${
                    block.type === 'note' ? 'bg-amber-500/10 border-amber-500/20' : 'bg-slate-800/40 border-slate-800/50'
                  }`}>
                    <span className={`text-[10px] font-bold uppercase tracking-widest ${
                      block.type === 'note' ? 'text-amber-400' : 'text-slate-400'
                    }`}>
                      {block.title}
                    </span>
                    <button
                      onClick={() => copyBlock(block.content, `block-${idx}`)}
                      className={`flex items-center space-x-1.5 px-3 py-1 rounded-md text-[11px] font-bold transition-all shadow-sm ${
                        copyStatus === `block-${idx}`
                          ? 'bg-emerald-500 text-white'
                          : 'bg-slate-700 hover:bg-slate-600 text-slate-200'
                      }`}
                    >
                      <i className={`fa-solid ${copyStatus === `block-${idx}` ? 'fa-check' : 'fa-copy'}`}></i>
                      <span>{copyStatus === `block-${idx}` ? 'TERSALIN!' : 'COPY'}</span>
                    </button>
                  </div>
                  <div className="p-4">
                    <pre className="text-slate-300 text-sm font-sans whitespace-pre-wrap leading-relaxed">
                      {renderFormattedText(block.content)}
                    </pre>
                  </div>
                </div>
              ))
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-600 space-y-4 italic">
                <i className="fa-solid fa-clipboard-list text-4xl opacity-10"></i>
                <div className="text-center">
                  <p className="text-sm font-medium text-slate-500 not-italic">Belum Ada Hasil</p>
                  <p className="text-xs mt-1">Upload screenshot jadwal untuk generate teks WhatsApp.</p>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ScheduleModule;
